const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || {};
return [{ json: {
  keyId: String(headers['x-qhs-key-id'] || ''),
  ts: String(headers['x-qhs-timestamp'] || ''),
  nonce: String(headers['x-qhs-nonce'] || ''),
  signature: String(headers['x-qhs-signature'] || ''),
  payload: typeof body.payload === 'string' ? body.payload : '',
} }];

const item = $input.first().json;
const given = item.signature;
const wanted = 'v1=' + item.expected;
// Constant time: every character is compared whatever the first mismatch.
let diff = given.length ^ wanted.length;
for (let i = 0; i < wanted.length; i++) {
  diff |= wanted.charCodeAt(i) ^ given.charCodeAt(i % (given.length || 1));
}
const store = $getWorkflowStaticData('global');
store.nonces = store.nonces || {};
const now = Date.now();
for (const key of Object.keys(store.nonces)) {
  if (store.nonces[key] < now) { delete store.nonces[key]; }
}
let valid = diff === 0
  && item.keyId === 'n8n'
  && /^[0-9]+$/.test(item.ts)
  && Math.abs(now / 1000 - Number(item.ts)) <= 300
  && /^[a-f0-9]{32}$/.test(item.nonce)
  && !store.nonces[item.nonce];
let data = {};
if (valid) {
  try { data = JSON.parse(item.payload); } catch (error) { valid = false; }
}
if (valid) { store.nonces[item.nonce] = now + 600000; }
return [{ json: { valid, data } }];

const out = $input.first().json;
const text = String(out.merged_response || (out.content || []).map((part) => part.text || '').join(''));
let parsed = null;
try {
  parsed = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
} catch (error) {
  parsed = null;
}
const allowed = ['low', 'normal', 'high', 'urgent'];
const ok = parsed !== null && allowed.includes(parsed.priority);
return [{ json: {
  priority: ok ? parsed.priority : 'normal',
  reason: ok ? String(parsed.reason || '').slice(0, 280) : 'The AI answer could not be read, so the default priority is shown.',
  source: ok ? 'ai' : 'fallback',
} }];

const suggestion = $input.first().json;
const data = $('Verify Signature').first().json.data;
let nonce = '';
while (nonce.length < 32) { nonce += Math.floor(Math.random() * 16).toString(16); }
return [{ json: { payload: JSON.stringify({ booking_id: data.booking_id, priority: suggestion.priority, reason: suggestion.reason, source: suggestion.source }), ts: String(Math.floor(Date.now() / 1000)), nonce } }];
